			character,
			name,
			nameRomanized,
			nameMeaning,
			classType,
			hasDeadEnding,
			isAspirated,
			initialSound,
			finalSound,
			mnemonic ?? proseFor(sceneMnemonic),
			audioUrl,
			priority,
			lesson,
			sceneMnemonic,
		);
	}
}

export type VowelPosition =
	| "left"
	| "right"
	| "above"

